                if is_dsd {
                    let out_l = processor.channel_dsd(0);
                    let out_r = processor.channel_dsd(1);

                    let ov = processor.total_overload_count();
                    if ov > overload_events {
                        lifecycle.report_overload_trip();
                        overload_events = ov;
                    }

                    // Pack and emit
                    let frames = pack_and_write_stereo_dsd(
